package zitadel

import (
	"context"
	"encoding/base64"
	"fmt"
	"net/http"
	"strings"
)

// EnsureMachineKeyUser provisions a machine user that authenticates with a
// private-key JWT whose PUBLIC key the caller supplies, and grants it roles in a
// project (kamarkat ADR-116 §3, the kakt-agent identity).
//
// The key pair is generated by whoever will sign with it -- kakt -- and only the
// public half is declared in the box. So no private key is ever minted here or
// carried out of the box, and the tenant revokes the identity by removing the
// declaration.
//
// knownKeyID is the key this public key was registered as on an earlier call.
// When it still exists nothing is added; when it does not (or none is known),
// the key is registered and its new id returned. revokeKeyID, when set and
// different, is removed: the previous public key the tenant replaced.
//
//	POST   /management/v1/users/{id}/keys          AddMachineKeyRequest{type, public_key}
//	POST   /management/v1/users/{id}/keys/_search  ListMachineKeys
//	DELETE /management/v1/users/{id}/keys/{keyId}  RemoveMachineKey
func (a *Auth) EnsureMachineKeyUser(ctx context.Context, orgID, projectID, userName, publicKeyPEM, knownKeyID, revokeKeyID string, roles []string) (userID, keyID string, err error) {
	if orgID == "" || projectID == "" {
		return "", "", fmt.Errorf("zitadel: a machine key user needs its resolved organisation and project")
	}
	if userName == "" || !strings.Contains(publicKeyPEM, "PUBLIC KEY") {
		return "", "", fmt.Errorf("zitadel: a machine key user needs a name and a PEM public key")
	}

	userID, tokenType, _, err := a.findMachineUser(ctx, orgID, userName)
	if err != nil {
		return "", "", err
	}
	if userID == "" {
		if userID, err = a.createMachineUser(ctx, orgID, userName, userName); err != nil {
			return "", "", err
		}
	} else if tokenType != accessTokenTypeJWT {
		if err := a.setMachineTokenTypeJWT(ctx, orgID, userID, userName, userName); err != nil {
			return "", "", err
		}
	}

	var keys struct {
		Result []struct {
			ID string `json:"id"`
		} `json:"result"`
	}
	if err := a.api.do(ctx, http.MethodPost, "/management/v1/users/"+userID+"/keys/_search", orgID,
		map[string]any{"query": map[string]any{"limit": 100}}, &keys); err != nil && !isNotFound(err) {
		return "", "", fmt.Errorf("list keys of machine user %q: %w", userName, err)
	}
	for _, k := range keys.Result {
		if knownKeyID != "" && k.ID == knownKeyID {
			keyID = k.ID
		}
	}
	if keyID == "" {
		var added struct {
			KeyID string `json:"keyId"`
		}
		body := map[string]any{
			"type":      "KEY_TYPE_JSON",
			"publicKey": base64.StdEncoding.EncodeToString([]byte(publicKeyPEM)),
		}
		if err := a.api.do(ctx, http.MethodPost, "/management/v1/users/"+userID+"/keys", orgID, body, &added); err != nil {
			return "", "", fmt.Errorf("register the public key of machine user %q: %w", userName, err)
		}
		if added.KeyID == "" {
			return "", "", fmt.Errorf("zitadel: key for machine user %q registered without an id", userName)
		}
		keyID = added.KeyID
	}
	if revokeKeyID != "" && revokeKeyID != keyID {
		for _, k := range keys.Result {
			if k.ID == revokeKeyID {
				if err := a.api.do(ctx, http.MethodDelete, "/management/v1/users/"+userID+"/keys/"+revokeKeyID, orgID, nil, nil); err != nil && !isNotFound(err) {
					return "", "", fmt.Errorf("remove the replaced key of machine user %q: %w", userName, err)
				}
			}
		}
	}

	if err := a.GrantRole(ctx, orgID, projectID, userID, roles); err != nil {
		return "", "", fmt.Errorf("grant %v to machine user %q: %w", roles, userName, err)
	}
	return userID, keyID, nil
}
